        long count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (city.equals(existing.getCity())) {
                count++;
            }
        }
        owner.setCapacityWarning(count >= WARNING_THRESHOLD && count < CITY_CAPACITY);
    }
}
